CREATE TABLE IF NOT EXISTS users (id text PRIMARY KEY, username text UNIQUE NOT NULL, password_hash text NOT NULL, role text NOT NULL CHECK (role IN ('admin','operator')));
CREATE TABLE IF NOT EXISTS sessions (token_hash text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id), expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS peers (id text PRIMARY KEY, owner text NOT NULL REFERENCES users(id), kind text NOT NULL CHECK(kind IN ('device','model')), name text NOT NULL, token_hash text UNIQUE NOT NULL, expires_at timestamptz NOT NULL, metadata jsonb NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS model_profiles (id text PRIMARY KEY, owner text NOT NULL REFERENCES users(id), config jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS assets (id text PRIMARY KEY, owner text NOT NULL REFERENCES users(id), mime text NOT NULL, bytes bigint NOT NULL, sha256 text NOT NULL, path text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS tasks (id text PRIMARY KEY, owner text NOT NULL REFERENCES users(id), idempotency_key text NOT NULL, request_hash text NOT NULL, spec jsonb NOT NULL, status text NOT NULL, error text NOT NULL DEFAULT '', iterations integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(owner,idempotency_key));
CREATE TABLE IF NOT EXISTS device_leases (device_id text PRIMARY KEY REFERENCES peers(id), holder text NOT NULL, generation bigint NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS observations (id text PRIMARY KEY, device_id text NOT NULL REFERENCES peers(id), task_id text REFERENCES tasks(id), owner text NOT NULL REFERENCES users(id), asset_id text NOT NULL REFERENCES assets(id), width integer NOT NULL, height integer NOT NULL, state jsonb NOT NULL, captured_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS device_commands (id text PRIMARY KEY, task_id text REFERENCES tasks(id), device_id text NOT NULL REFERENCES peers(id), holder text NOT NULL, generation bigint NOT NULL, observation_id text NOT NULL REFERENCES observations(id), action jsonb NOT NULL, status text NOT NULL, error text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS command_reconcile_idx ON device_commands(device_id,status);
CREATE TABLE IF NOT EXISTS task_events (id bigserial PRIMARY KEY, task_id text NOT NULL REFERENCES tasks(id), type text NOT NULL, data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS task_events_cursor_idx ON task_events(task_id,id);
CREATE TABLE IF NOT EXISTS agent_checkpoints (id text PRIMARY KEY, data bytea NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS model_calls (id text PRIMARY KEY, task_id text NOT NULL REFERENCES tasks(id), profile_id text NOT NULL, observation_id text NOT NULL REFERENCES observations(id), duration_ms bigint NOT NULL, usage jsonb, error text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS model_requests (id text PRIMARY KEY, task_id text NOT NULL REFERENCES tasks(id), observation_id text NOT NULL REFERENCES observations(id), connector_id text, status text NOT NULL, deadline timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
